-- ============================================================

-- Update COD Policy with official content
UPDATE policies
SET 
  content = E'# J-STORE Cash on Delivery (COD) Policy\n\nEffective Date: [Insert Date]\n\n## 1. Purpose\n\n<cite index="1-2,1-3">This Cash on Delivery (COD) Policy explains the terms and conditions governing Cash on Delivery orders placed through J-STORE. The purpose of this policy is to provide customers with a convenient payment option while protecting sellers, delivery partners, and J-STORE from fraud, abuse, and unnecessary losses.</cite>\n\n## 2. Definition of Cash on Delivery\n\n<cite index="1-5,1-6">Cash on Delivery (COD) allows eligible customers to place orders through J-STORE and pay all or part of the purchase price upon successful delivery of the product. J-STORE reserves the right to determine which products, sellers, customers, locations, and order values qualify for COD.</cite>\n\n## 3. Eligibility for COD\n\n<cite index="1-8,1-9,1-10,1-11">J-STORE may offer COD to:\n- Eligible customers.\n- Approved delivery locations.\n- Selected products and categories.\n- Customers with a satisfactory order history.</cite>\n\n<cite index="1-12">J-STORE reserves the right to restrict or deny COD for any order at its sole discretion.</cite>\n\n## 4. Deposit Requirements\n\n<cite index="1-14,1-15,1-16,1-17">For certain orders, J-STORE may require:\n- A delivery fee payment before processing.\n- A partial deposit.\n- Identity verification.\n- Full prepayment for specific products or locations.</cite>\n\n<cite index="1-18">Required deposits are generally non-refundable where customer cancellation occurs after order processing has begun.</cite>\n\n## 5. Order Confirmation\n\n<cite index="1-20,1-21,1-22">Customers placing COD orders may be required to:\n- Confirm their phone number.\n- Confirm delivery details.\n- Respond to verification calls or messages.</cite>\n\n<cite index="1-23">Orders that cannot be verified may be cancelled without notice.</cite>\n\n## 6. Customer Responsibilities\n\n<cite index="1-25,1-26,1-27,1-28">Customers agree to:\n- Provide accurate contact information.\n- Provide an accurate delivery address.\n- Be available to receive the order.\n- Make payment upon delivery as agreed.</cite>\n\n<cite index="1-29">Failure to comply may result in order cancellation or account restrictions.</cite>\n\n## 7. Refusal of Delivery\n\n<cite index="1-31,1-32,1-33">Customers may refuse delivery when:\n- The wrong product is delivered.\n- The product is visibly damaged.\n- The delivered item significantly differs from the order.</cite>\n\n<cite index="1-34">Customers may not refuse delivery without reasonable justification after confirming an order.</cite>\n\n<cite index="1-35">Repeated unjustified refusals may result in suspension of COD privileges.</cite>\n\n## 8. Failed Deliveries\n\n<cite index="1-37,1-38,1-39,1-40">A delivery may be considered failed if:\n- The customer is unavailable.\n- The customer cannot be contacted.\n- The delivery address is incorrect.\n- The customer refuses delivery without valid reason.</cite>\n\n<cite index="1-41">J-STORE reserves the right to charge additional delivery fees for repeated delivery attempts.</cite>\n\n## 9. COD Restrictions\n\n<cite index="1-43,1-44,1-45,1-46,1-47">J-STORE may restrict COD for:\n- High-value products.\n- Special-order products.\n- Customized products.\n- Certain geographic areas.\n- Customers with a history of failed deliveries or order refusals.</cite>\n\n## 10. Fraud Prevention\n\n<cite index="1-49,1-50,1-51,1-52,1-53">J-STORE reserves the right to:\n- Verify customer identities.\n- Verify delivery information.\n- Record communication related to orders.\n- Cancel suspicious transactions.\n- Restrict accounts involved in fraudulent activities.</cite>\n\n## 11. Seller Protection\n\n<cite index="1-55,1-56,1-57">Where a customer refuses delivery without valid reason, J-STORE may:\n- Restrict future COD access.\n- Recover delivery-related losses where legally permitted.\n- Take measures to protect sellers from repeated abuse.</cite>\n\n## 12. Delivery Partner Protection\n\n<cite index="1-59">Customers shall treat delivery personnel respectfully and professionally.</cite>\n\n<cite index="1-60">Abusive, threatening, or fraudulent conduct may result in account suspension and possible legal action.</cite>\n\n## 13. Limitation of Liability\n\n<cite index="1-62">J-STORE shall not be liable for delays, delivery interruptions, force majeure events, transportation disruptions, or circumstances beyond its reasonable control.</cite>\n\n## 14. Violations\n\n<cite index="1-64,1-65,1-66,1-67,1-68">Violations of this Policy may result in:\n- Warning notices.\n- Temporary suspension of COD privileges.\n- Account restrictions.\n- Permanent account termination.\n- Additional verification requirements for future orders.</cite>\n\n## 15. Policy Changes\n\n<cite index="1-70">J-STORE reserves the right to modify this Policy at any time to improve operational efficiency, customer experience, and marketplace security.</cite>\n\n<cite index="1-71">By placing a Cash on Delivery order through J-STORE, the customer acknowledges and agrees to this Policy.</cite>',
  title = 'Cash on Delivery (COD) Policy',
  version = '1.0',
  updated_at = now()
WHERE type = 'cod_policy';

-- Update Marketplace Rules with official content
UPDATE policies
SET
  content = E'# J-STORE Marketplace Rules\n\nEffective Date: [Insert Date]\n\n<cite index="2-1">The purpose of these Marketplace Rules is to maintain a safe, trusted, and professional environment for buyers and sellers.</cite>\n\n## 1. Seller Conduct\n\n<cite index="2-3,2-4,2-5,2-6,2-7">All sellers must:\n- Treat customers professionally.\n- Provide accurate product information.\n- Maintain product availability.\n- Deliver products within agreed timelines.\n- Comply with all J-STORE policies.</cite>\n\n## 2. Prohibited Products\n\n<cite index="2-9,2-10,2-11,2-12,2-13,2-14,2-15,2-16">The following products may not be listed on J-STORE:\n- Illegal products.\n- Counterfeit goods.\n- Stolen items.\n- Weapons prohibited by law.\n- Dangerous drugs or controlled substances.\n- Pornographic materials.\n- Products that violate intellectual property rights.\n- Any product prohibited by Cameroonian law.</cite>\n\n<cite index="2-17">J-STORE reserves the right to remove any listing at its discretion.</cite>\n\n## 3. Product Listings\n\n<cite index="2-19,2-20,2-21,2-22">All listings must:\n- Use genuine images.\n- Include accurate descriptions.\n- Display truthful pricing.\n- Avoid misleading claims.</cite>\n\n## 4. Customer Communication\n\n<cite index="2-24">Customers shall communicate through official J-STORE channels.</cite>\n\n<cite index="2-25">Sellers shall not attempt to redirect customers outside the platform without authorization from J-STORE.</cite>\n\n## 5. Fraud and Abuse\n\n<cite index="2-27,2-28,2-29,2-30,2-31,2-32">The following activities are strictly prohibited:\n- Fake orders.\n- Fake reviews.\n- False advertising.\n- Identity fraud.\n- Manipulation of prices.\n- Abuse of promotions or discounts.</cite>\n\n## 6. Order Fulfillment Standards\n\n<cite index="2-34,2-35,2-36,2-37">Sellers must:\n- Confirm orders promptly.\n- Prepare products accurately.\n- Cooperate with delivery arrangements.\n- Notify J-STORE of any fulfillment issues.</cite>\n\n## 7. Complaints and Disputes\n\n<cite index="2-39">All disputes shall be handled through J-STORE\'s official complaint resolution process.</cite>\n\n<cite index="2-40">The decision of J-STORE regarding marketplace disputes shall be final unless otherwise required by law.</cite>\n\n## 8. Violations and Penalties\n\n<cite index="2-42,2-43,2-44,2-45,2-46">J-STORE may take the following actions:\n- Warning notices.\n- Listing removal.\n- Temporary suspension.\n- Permanent account termination.\n- Legal action where appropriate.</cite>\n\n## 9. Platform Integrity\n\n<cite index="2-48">J-STORE reserves the right to monitor marketplace activities and take any necessary action to protect customers, sellers, and the platform.</cite>\n\n## 10. Commitment to Trust\n\n<cite index="2-50">All marketplace participants agree to uphold honesty, fairness, transparency, and professionalism while using J-STORE.</cite>',
  title = 'Marketplace Rules',
  version = '1.0',
  updated_at = now()
WHERE type = 'marketplace_rules';

-- Update Seller Agreement with official content
UPDATE policies
SET
  content = E'# J-STORE Seller Agreement\n\nEffective Date: [Insert Date]\n\n<cite index="3-1">This Seller Agreement governs participation as a seller on J-STORE.</cite>\n\n## Seller Eligibility\n\n<cite index="3-2,3-3,3-4">Sellers must:\n- Provide accurate identification information.\n- Provide valid contact details.\n- Comply with applicable laws.</cite>\n\n## Seller Responsibilities\n\n<cite index="3-5,3-6,3-7,3-8,3-9">Sellers agree to:\n- Provide genuine products.\n- Maintain accurate inventory.\n- Deliver products within agreed timelines.\n- Respond promptly to J-STORE communications.\n- Maintain professional conduct.</cite>\n\n## Product Standards\n\n<cite index="3-10,3-11,3-12">Products must:\n- Match descriptions and images.\n- Be legally permitted for sale.\n- Meet applicable quality standards.</cite>\n\n## Commission and Fees\n\n<cite index="3-13">J-STORE may charge commissions, listing fees, advertising fees, or other marketplace charges as communicated to sellers.</cite>\n\n## Seller Verification\n\n<cite index="3-14,3-15">J-STORE reserves the right to verify seller identity, business information, and product authenticity.</cite>\n\n## Suspensions\n\n<cite index="3-16">J-STORE may suspend or terminate seller accounts for:\n- Fraudulent activity\n- Repeated customer complaints\n- Sale of prohibited products\n- Violation of marketplace policies</cite>\n\n## Intellectual Property\n\n<cite index="3-16">Sellers grant J-STORE permission to display product images, descriptions, trademarks, and promotional materials for marketplace purposes.</cite>\n\n## Dispute Resolution\n\n<cite index="3-17">Sellers agree to cooperate with J-STORE during customer complaints, refund requests, and investigations.</cite>\n\n## Agreement Acceptance\n\n<cite index="3-18">By registering as a seller, the seller agrees to be bound by this Agreement.</cite>',
  title = 'Seller Agreement',
  version = '1.0',
  updated_at = now()
WHERE type = 'seller_agreement';

-- Update Privacy Policy with official content
UPDATE policies
SET
  content = E'# J-STORE Privacy Policy\n\nEffective Date: [Insert Date]\n\n<cite index="5-1">J-STORE values your privacy and is committed to protecting your personal information.</cite>\n\n## Information We Collect\n\n<cite index="5-2">We may collect:\n- Full name\n- Email address\n- Phone number\n- Delivery information\n- Payment information\n- Device and browsing information</cite>\n\n## How We Use Information\n\n<cite index="5-2">We use collected information to:\n- Process orders\n- Verify accounts\n- Improve services\n- Provide customer support\n- Send important notifications</cite>\n\n## Information Sharing\n\n<cite index="5-2">J-STORE does not sell user information.</cite>\n\n<cite index="5-3">Information may be shared with:\n- Approved sellers for order fulfillment\n- Delivery partners\n- Payment service providers\n- Government authorities where legally required</cite>\n\n## Data Security\n\n<cite index="5-4">We implement reasonable technical and administrative measures to protect user information.</cite>\n\n## User Rights\n\n<cite index="5-5">Users may:\n- Request access to their information\n- Request corrections\n- Request account closure where applicable</cite>\n\n## Cookies\n\n<cite index="5-5">J-STORE may use cookies and similar technologies to improve platform performance and user experience.</cite>\n\n## Policy Updates\n\n<cite index="5-6">This Privacy Policy may be updated periodically.</cite>',
  title = 'Privacy Policy',
  version = '1.0',
  updated_at = now()
WHERE type = 'privacy_policy';

-- Add return/refund policy (bonus from your documents)
INSERT INTO policies (type, title, content, version, effective_date)
VALUES (
  'return_policy',
  'Refund Policy',
  E'# J-STORE Refund Policy\n\nEffective Date: [Insert Date]\n\n<cite index="4-1,4-2">At J-STORE, customer satisfaction is important to us. This Refund Policy outlines the conditions under which refunds, returns, replacements, and order cancellations may be processed.</cite>\n\n## 1. Eligibility for Refunds\n\n<cite index="4-4,4-5,4-6,4-7,4-8">Customers may be eligible for a refund if:\n- The product received is significantly different from the description.\n- The wrong product was delivered.\n- The product is defective or damaged upon delivery.\n- The order was paid for but not delivered.\n- The seller is unable to fulfill the order.</cite>\n\n## 2. Non-Refundable Situations\n\n<cite index="4-10,4-11,4-12,4-13">Refunds may not be granted when:\n- The customer changes their mind after delivery.\n- The product has been used, damaged, or altered by the customer.\n- The customer provides an incorrect delivery address.\n- The refund request is submitted outside the approved complaint period.</cite>\n\n## 3. Refund Request Process\n\n<cite index="4-15,4-16,4-17">To request a refund, customers must:\n- Contact J-STORE Customer Support.\n- Provide order details.\n- Provide evidence where applicable, including photos, videos, or screenshots.</cite>\n\n<cite index="4-18">J-STORE may investigate the complaint before making a final decision.</cite>\n\n## 4. Return of Products\n\n<cite index="4-20,4-21">Where required, products must be returned in their original condition, packaging, and with all accessories.</cite>\n\n## 5. Refund Approval\n\n<cite index="4-23">J-STORE reserves the right to approve or reject refund requests based on available evidence and investigation findings.</cite>\n\n## 6. Processing Time\n\n<cite index="4-25">Approved refunds shall be processed within a reasonable period through the original payment method where possible.</cite>\n\n## 7. Seller Responsibility\n\n<cite index="4-27">Sellers agree to cooperate fully in refund investigations and resolutions.</cite>\n\n<cite index="4-28">Failure to cooperate may result in account suspension or termination.</cite>\n\n## 8. Fraud Prevention\n\n<cite index="4-30">J-STORE reserves the right to reject fraudulent or abusive refund claims.</cite>',
  '1.0',
  CURRENT_DATE
)
ON CONFLICT (type) DO UPDATE
SET 
  content = EXCLUDED.content,
  title = EXCLUDED.title,
  updated_at = now();
